let name = $props.name;
let count = $state($props.count);
let showDetails = $props.showDetails;

function increment() {
  count = count + 1;
}

function getDetails() {
  return `Name is ${name}, Count is ${count}, ShowDetails is ${showDetails}`;
}

function renderDetails() {
  if (showDetails) {
    return `
      <p>Name is ${name}</p>
      <p>Count is ${count}</p>
      <p>ShowDetails is ${showDetails}</p>
    `;
  }
  return '';
}

$: detailsContent = renderDetails();

export function PropsDemo() {
  return (
    <div>
      <h1 data-testid="name-display">{name}</h1>
      <p data-testid="count-display">Count: {count}</p>
      <button data-testid="increment-button" on:click={increment}>Increment</button>

      {#if showDetails}
        <div data-testid="details">
          {detailsContent}
        </div>
      {/if}
    </div>
  );
}
